const certs = $input.all().map(i => i.json);
const now = new Date();
const results = [];

certs.forEach(cert => {
  const expiryDate = new Date(cert.expiryDate);
  const daysUntilExpiry = Math.floor((expiryDate - now) / (1000 * 60 * 60 * 24));

  if (daysUntilExpiry <= 60 && daysUntilExpiry > 0) {
    results.push({
      ...cert,
      daysUntilExpiry,
      urgency: daysUntilExpiry <= 30 ? 'urgent' : 'warning',
      alertType: daysUntilExpiry <= 30 ? '30-day' : '60-day'
    });
  } else if (daysUntilExpiry <= 0) {
    results.push({
      ...cert,
      daysUntilExpiry,
      urgency: 'expired',
      alertType: 'expired'
    });
  }
});

return results.map(r => ({ json: r }));

const trainings = $input.all().map(i => i.json);
const thisMonth = new Date().toISOString().slice(0, 7);
const completedThisMonth = trainings.filter(t => t.completedDate && t.completedDate.startsWith(thisMonth));
const totalCompleted = trainings.filter(t => t.status === 'completed').length;
const inProgress = trainings.filter(t => t.status === 'in_progress').length;

return [{ json: {
  completedThisMonth: completedThisMonth.length,
  totalCompleted,
  inProgress,
  month: thisMonth,
  details: completedThisMonth.map(t => `${t.employeeName}: ${t.trainingName}`).join(', ')
}}];
